use super::*;
fn template()->Value{serde_json::from_str(PLAN).unwrap()}
#[test]fn unbound_source_template_cannot_execute(){assert!(plan_contract(&template()).is_err());}
#[test]fn no_ending_launch_or_reader_authority_flag_can_be_promoted(){let mut p=template();p["template_requires_root_binding"]=json!(false);assert!(plan_contract(&p).is_ok());for key in["resource_promise_ending_authorized","replay_launch_authorized","native_Frame_or_full_Reader_authority","future_host_or_shared_role_bound_claimed"]{let mut changed=p.clone();changed[key]=json!(true);assert!(plan_contract(&changed).is_err());}}
#[test]fn historical_kernel_fulfillment_cannot_be_reused_as_shared_credit(){let mut p=template();p["template_requires_root_binding"]=json!(false);p["historical_kernel_fulfillment_reused"]=json!(true);assert!(plan_contract(&p).is_err());}
#[test]fn a_smaller_shared_reserve_is_never_selected_by_this_report(){let mut p=template();p["template_requires_root_binding"]=json!(false);p["retained_shared_bytes"]=json!(24u64<<30);assert!(plan_contract(&p).is_err());}
#[test]fn changed_boot_argv_cgroup_or_source_are_endpoint_failed_gates(){let a=json!({"boot_id":"a","kernel_release":"6.8","units":{},"installed_unit_files":{},"unit_sources":{},"processes":{"41":{"pid":41,"parent_pid":1,"start_ticks":71,"flags":0,"kernel_thread":false,"image":{},"argv":["x"],"cgroup":"/a"}},"cgroups":{"/a":{"memory.max":"16"}}});for key in["boot_id","unit_sources"]{let mut b=a.clone();b[key]=json!("changed");assert!(!endpoint_changes(&a,&b).is_empty());}let mut b=a.clone();b["processes"]["41"]["argv"]=json!(["y"]);assert!(!endpoint_changes(&a,&b).is_empty());b=a.clone();b["processes"]["41"]["cgroup"]=json!("/escaped");assert!(!endpoint_changes(&a,&b).is_empty());}
#[test]fn volatile_scheduler_state_does_not_falsely_change_identity(){let a=json!({"boot_id":"a","kernel_release":"6.8","units":{},"installed_unit_files":{},"unit_sources":{},"processes":{"41":{"pid":41,"parent_pid":1,"start_ticks":71,"flags":0,"kernel_thread":false,"image":{},"argv":["x"],"cgroup":"/a","state":"S"}},"cgroups":{}});let mut b=a.clone();b["processes"]["41"]["state"]=json!("R");assert!(endpoint_changes(&a,&b).is_empty());}
#[test]fn native_lock_proof_requires_exact_held_exclusive_write_owner_and_inode(){let raw="1: FLOCK ADVISORY WRITE 42 08:01:123 0 EOF\n";assert!(lock_record(raw,0x801,123,42));assert!(!lock_record(raw,0x801,123,43));assert!(!lock_record(raw,0x801,124,42));assert!(!lock_record("1: FLOCK ADVISORY READ 42 08:01:123 0 EOF",0x801,123,42));assert!(!lock_record("1: -> FLOCK ADVISORY WRITE 42 08:01:123 0 EOF",0x801,123,42));}
#[test]fn native_callback_does_not_hide_the_root_outer_booking(){let v=json!({"schema":"horizon-whole-role-native16-actual-booking-v1","retained_native16_bytes":16u64<<30,"existing_commitments_bytes":13_757_317_120u64,"native_callback_bytes":512u64<<20,"separate_root_outer_bytes":0,"compiler_concurrent":false,"all_original_promises_retained":true,"actual_ledger_evidence":[]});let error=native_accounting(&v).unwrap_err().to_string();assert!(error.contains("distinct")||error.contains("separate Root outer"));}

#[test]fn disappearing_pid_or_cgroup_records_failed_gate_without_map_index_panic(){let a=json!({"boot_id":"a","kernel_release":"6.8","units":{},"installed_unit_files":{},"unit_sources":{},"processes":{"41":{"pid":41,"parent_pid":1,"start_ticks":71,"flags":0,"kernel_thread":false,"image":{},"argv":["x"],"cgroup":"/a"}},"cgroups":{"/a":{"memory.max":"16"}}});let mut b=a.clone();b["processes"]=json!({});b["cgroups"]=json!({});let issues=endpoint_changes(&a,&b);assert!(issues.iter().any(|i|i["gate"]=="process-disappeared-between-endpoints"));assert!(issues.iter().any(|i|i["gate"]=="cgroup-disappeared-between-endpoints"));}
